"""Extract Gen II capture wobble thresholds and throw-script waits, without ROMs."""
from pathlib import Path
import re,json,sys,subprocess
r=Path(sys.argv[1] if len(sys.argv)>1 else '/private/tmp/pokemon-gold-kr-research')
o=Path(__file__).resolve().parent.parent
script=(r/'data/moves/animations.asm').read_text().split('BattleAnim_ThrowPokeBall:')[1].split('BattleAnim_SendOutMon:')[0]
throw=[int(x) for x in re.findall(r'anim_wait (\d+)',script.split('.TheTrainerBlockedTheBall:')[0])]
shake=[int(x) for x in re.findall(r'anim_wait (\d+)',script.split('.Shake:')[1].split('.Loop:')[0])]
check=int(re.search(r'anim_wait (\d+)',script.split('.Loop:')[1])[1])
prob=[[int(a),int(b)] for a,b in re.findall(r'db\s+(\d+),\s*(\d+)',(r/'data/battle/wobble_probabilities.asm').read_text())]
assert throw==[36,16,16] and shake==[8,16,32,32,32,32,8] and check==48
frames={'throw':throw[0],'open':throw[1],'poof':throw[2],'absorb':shake[0],'close':shake[1],'bounce':sum(shake[2:6]),'settle':shake[6],'check':check,'wobble':35,'escape':32,'lock':32}
source={'repository':'https://github.com/Narishma-gb/pokegold-kr','commit':subprocess.check_output(['git','-C',str(r),'rev-parse','HEAD'],text=True).strip(),'files':['data/moves/animations.asm','engine/battle_anims/functions.asm','engine/battle_anims/pokeball_wobble.asm','data/battle/wobble_probabilities.asm','data/battle_anims/framesets.asm']}
normal=(r/'data/moves/animations.asm').read_text().split('BattleAnim_SendOutMon:')[1].split('.Normal:')[1].split('BattleAnim_ReturnMon:')[0]
enter=[int(x) for x in re.findall(r'anim_wait (\d+)',normal)]
assert enter==[4,32]
(o/'capture-source.js').write_text('// Generated by tools/build_capture_assets.py from the pinned Gold disassembly.\nexport const CAPTURE_FRAMES='+json.dumps(frames,separators=(',',':'))+';\nexport const SENDOUT_FRAMES='+json.dumps({'poof':enter[0],'enter':enter[1],'recall':32},separators=(',',':'))+';\nexport const WOBBLE_PROBABILITIES='+json.dumps(prob,separators=(',',':'))+';\nexport const CAPTURE_SOURCE='+json.dumps(source,separators=(',',':'))+';\n')
print('Extracted',len(prob),'wobble thresholds and original capture frame waits')
